/*
 * A192590  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S and xy-3 is a prime, then xy-3 is in S, and 2 and 4 are
 *          in S.
 * https://oeis.org/A192590
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   not stated
 * Range:     u8 n <= 13, u16 n <= 26, u32 n <= 26, u64 n <= 26, u128 n <= 26,
 *            big any n
 * Helpers:   floor_sqrt, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes OEIS A192590 by generating its monotonic set S.
 * 2 and 4 are in S.  If x,y∈S and xy‑3 is prime, then xy‑3∈S.
 * The sequence a(n) is the nth smallest element of S. */

#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include "../utils/is_prime_big.h"
#include "../utils/floor_sqrt.h"

/* binary search on sorted array S[0..len-1]: if found *pos = index, returns true.
 * otherwise *pos = insertion point, returns false. */
static bool binary_search(const seq_t *S, size_t len, seq_t val, size_t *pos)
{
    size_t lo = 0, hi = len;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        if (S[mid] < val)
            lo = mid + 1;
        else
            hi = mid;
    }
    *pos = lo;
    return (lo < len && S[lo] == val);
}

/* Ensure that the array *arr has capacity at least needed. */
static void ensure_cap(void **arr, size_t *cap, size_t needed)
{
    if (needed > *cap) {
        size_t newcap = (*cap > 0) ? (*cap << 1) : 64;
        while (newcap < needed)
            newcap <<= 1;
        *arr = realloc(*arr, newcap * sizeof(seq_t));
        *cap = newcap;
    }
}

seq_t a(idx_t n)
{
    if (n < 1)
        return 0;                     /* undefined for n<1 */

    /* static state persistent between calls */
    static seq_t *S = NULL;
    static size_t S_cap = 0, S_sz = 0;
    static idx_t last_checked = 0;

    /* initialise S with 2 and 4 if needed */
    if (S_sz == 0) {
        ensure_cap((void **)&S, &S_cap, 2);
        S[0] = 2;
        S[1] = 4;
        S_sz = 2;
    }

    /* generate until we have at least n elements */
    while (S_sz < (size_t)n) {

        /* find the next prime p that satisfies the rule */
        for (;;) {
            last_checked++;                     /* next integer to test */
            seq_t p = (seq_t)last_checked;

            if (!is_prime_big(p))
                continue;

            size_t pos;
            if (binary_search(S, S_sz, p, &pos))
                continue;                      /* already in S */

            seq_t cand = p + (seq_t)3;          /* xy‑3 = candidate’s +3 */
            seq_t limit = floor_sqrt(cand);
            bool ok = false;

            /* look for a factorisation cand = x*y with x,y∈S */
            for (size_t i = 0; i < S_sz; ++i) {
                seq_t x = S[i];
                if (x > limit)
                    break;
                if (cand % x != 0)
                    continue;
                seq_t y = cand / x;
                if (binary_search(S, S_sz, y, &pos)) {
                    ok = true;
                    break;
                }
            }

            if (ok) {
                /* insert p into S keeping it sorted */
                ensure_cap((void **)&S, &S_cap, S_sz + 1);
                binary_search(S, S_sz, p, &pos);
                memmove(&S[pos + 1], &S[pos], (S_sz - pos) * sizeof(seq_t));
                S[pos] = p;
                ++S_sz;
                break;                          /* go back to while(S_sz<n) */
            }
        }
    }

    return S[n - 1];
}
